import assert from 'node:assert/strict';

const alpha = 'aAbBcCzZ09 -_.';
const rnd = (n) => Math.floor(Math.random() * n);
let fails = 0, count = 0;
function check(label, fn, args) {
  count++;
  try {
    const a = fn.A(...args), b = fn.B(...args);
    assert.equal(JSON.stringify(b), JSON.stringify(a));
  } catch (e) {
    fails++;
    if (fails <= 10) console.log('MISMATCH', label, JSON.stringify(args), '\n  orig:', JSON.stringify(A[label](...args)), '\n  new :', JSON.stringify(B[label](...args)));
