for (const s of fixed) check('tokens', { A: A.tokens, B: B.tokens }, [s]);
for (let i = 0; i < 200000; i++) {
  const len = rnd(41);
  let s = '';
  for (let j = 0; j < len; j++) s += alpha[rnd(alpha.length)];
  check('tokens', { A: A.tokens, B: B.tokens }, [s]);
}
// byAge
const names = ['kim', 'lee', 'park', 'choi', 'jung'];
const mkRow = () => ({ id: rnd(10), name: names[rnd(5)], age: 18 + rnd(43) });
for (let i = 0; i < 50000; i++) {
  const rows = Array.from({ length: rnd(13) }, mkRow);
  check('byAge', { A: A.byAge, B: B.byAge }, [rows]);
}
// toLookup
for (let i = 0; i < 50000; i++) {
  const pairs = Array.from({ length: rnd(9) }, () => [names[rnd(5)], rnd(100)]);
  check('toLookup', { A: A.toLookup, B: B.toLookup }, [pairs]);
}
// example inputs
check('byAge', { A: A.byAge, B: B.byAge }, [[{"id":9,"name":"jung","age":59},{"id":3,"name":"kim","age":36},{"id":2,"name":"lee","age":40},{"id":1,"name":"kim","age":21},{"id":8,"name":"park","age":52},{"id":7,"name":"jung","age":41},{"id":6,"name":"jung","age":26},{"id":0,"name":"lee","age":39},{"id":5,"name":"lee","age":18},{"id":5,"name":"park","age":48},{"id":8,"name":"jung","age":37}]]);
check('toLookup', { A: A.toLookup, B: B.toLookup }, [[["jung",98],["jung",25]]]);
console.log('checked', count, 'mismatches', fails);
console.log('tokens example', JSON.stringify(B.tokens("Widthline_API.max")), JSON.stringify(B.tokens("max.widthSIZE ")));
